source = '''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    line_colors = set()
    for row in grid:
        if len(set(row)) == 1:
            line_colors.add(row[0])
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1:
            line_colors.add(col[0])
    if not line_colors:
        return [row[:] for row in grid]
    separator = min(line_colors, key=lambda color: counts[color])
    sep_rows = [r for r, row in enumerate(grid) if all(v == separator for v in row)]
    sep_cols = [c for c in range(w) if all(grid[r][c] == separator for r in range(h))]

    def ranges(length, separators):
        out, start = [], 0
        for pos in separators:
            if start < pos:
                out.append(list(range(start, pos)))
            start = pos + 1
        if start < length:
            out.append(list(range(start, length)))
        return out

    row_blocks = ranges(h, sep_rows)
    col_blocks = ranges(w, sep_cols)
    background = max((c for c in counts if c != separator), key=lambda c: counts[c])
    blocks = []
    for rr in row_blocks:
        for cc in col_blocks:
            cells = [[grid[r][c] for c in cc] for r in rr]
            score = sum(v != background for row in cells for v in row)
            blocks.append((score, cells))
    template = max(blocks, key=lambda item: item[0])[1]
    out = [row[:] for row in grid]
    th, tw = len(template), len(template[0])
    for rr in row_blocks:
        for cc in col_blocks:
            for i, r in enumerate(rr):
                for j, c in enumerate(cc):
                    out[r][c] = template[i % th][j % tw]
    return out
'''
